	'ip_st_c1_s' => '18 STANDS',
	'ip_st_c1_t' => 'Vin',
	'ip_st_c2_d' => 'Légumes de saison et brochettes cuits sur la braise de bois.',
	'ip_st_c2_s' => '12 STANDS',
