	'nl_caps' => 'Liste d\'attente',
	'nl_h1' => 'Rejoindre la liste d\'attente Hozue',
	'nl_lede' => 'Les actualités du programme, les annonces de billetterie et la date de fin du tarif prévente, en un seul e-mail court.',
	'pe1_d' => 'Lave et affine ses fromages à croûte au lait des prairies régionales, et découpe chaque meule à la demande à son comptoir.',
	'pe1_n' => 'Hélène Varga',
	'pe1_r' => 'Fromagère',
	'pe2_d' => 'Sert des vins peu interventionnistes issus de vignes en coteaux et anime les dégustations guidées sous le chapiteau des vins.',
	'pe2_n' => 'Tomás Achterberg',
	'pe2_r' => 'Vigneron, Achterberg Hill',
	'pe3_d' => 'Grille des légumes de saison et des brochettes sur la braise de bois sur la pelouse gourmande, selon les récoltes des producteurs.',
	'pe3_n' => 'Priya Ramanathan',
	'pe3_r' => 'Cuisinière, brochettes au feu de bois',
	'pe4_d' => 'Apporte chaque matin tomates anciennes, haricots à rames et légumes verts d\'été depuis ses champs aux portes d\'Alderford.',
	'pe4_n' => 'Joseph Mwangi',
	'pe4_r' => 'Maraîcher',
	'pe5_d' => 'Cuit du pain au levain naturel au four à bois et anime la session Pain & feu du dimanche.',
